type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Get the length of the input array
    let a_len = a.len();
    
    // Check which dimension matches the array length
    if a_len == r {
        // Array length matches rows: treat as column vector
        // Each row gets the same element from array at row index
        (0..r)
            .map(|i| {
                // Create a row with C copies of a[i]
                vec![a[i]; c]
            })
            .collect()
    } else if a_len == c {
        // Array length matches columns: treat as row vector
        // Each row gets the entire array
        (0..r)
            .map(|_| {
                // Copy the entire array for each row
                a.clone()
            })
            .collect()
    } else {
        // According to the problem statement, one dimension must match,
        // so this case shouldn't happen with valid inputs
        panic!("Array length must match either R or C");
    }
}